#[target_feature(enable = "avx512bw,ssse3")]
fn test_x86_avx512bw_mm_mask_alignr_epi8_vs_unmasked_impl() -> Result<Verdict, String> {
        if !(std::arch::is_x86_feature_detected!("ssse3")) {
            return Ok(Verdict::Skipped("ssse3 not present"));
        }
    unsafe {
        let a = create__m128i_from_i32_array([1, 2, 3, 4]);
        let b = create__m128i_from_i32_array([5, 6, 7, 8]);
        let src = create__m128i_from_i32_array([9, 10, 11, 12]);
        let k = create__mmask16_from(0b0101010101010101);
        let masked = unpack__m128i_to_i8_array(_mm_mask_alignr_epi8::<0>(src, k, a, b));
        let plain = unpack__m128i_to_i8_array(_mm_alignr_epi8::<0>(a, b));
        let src_lanes = unpack__m128i_to_i8_array(src);
        let expected: [i8; 16] = core::array::from_fn(|i| if (k >> i) & 1 == 1 { plain[i] } else { src_lanes[i] });
        check_array_equality(&masked, &expected).map_err(|e| crate::cpu::with_call(e, "_mm_mask_alignr_epi8::<0>(src, k, a, b) vs _mm_alignr_epi8::<0>(a, b)"))?;
        Ok(Verdict::Checked)
    }
}

